CREATE OR REPLACE FUNCTION public.billing_admin_save_plan(p_id uuid DEFAULT NULL,p_name text DEFAULT NULL,p_capacity integer DEFAULT NULL,p_amount bigint DEFAULT NULL,p_published boolean DEFAULT true) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_name IS NULL OR p_capacity IS NULL OR p_published IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 80 OR p_capacity<5 OR p_capacity%5<>0 OR p_amount<0 THEN RAISE EXCEPTION 'Invalid plan'; END IF; IF p_id IS NULL THEN INSERT INTO public.billing_plans(name,capacity,monthly_amount,published) VALUES(trim(p_name),p_capacity,p_amount,p_published) RETURNING id INTO result; ELSE UPDATE public.billing_plans SET name=trim(p_name),capacity=p_capacity,monthly_amount=p_amount,published=p_published,price_revision=price_revision+1,provider_monthly_price=NULL,provider_annual_price=NULL,updated_at=now() WHERE id=p_id RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Unknown plan'; END IF; END IF; RETURN result; END $$;